    'RegisterSimpleRisk'=>'Зарегистрировать SimpleRisk',
    'RegistrationText'=>'Зарегистрированные экземпляры SimpleRisk немедленно получают доступ к дополнительным функциям Upgrade and Secure Controls Framework (SCF). Upgrade Extra предоставляет возможность резервного копирования и обновления вашего экземпляра SimpleRisk одним нажатием кнопки. Платформа безопасного управления (SCF) Extra обеспечивает общую структуру управления, интегрированную в функциональность SimpleRisk Governance. После регистрации SimpleRisk ваша регистрационная информация будет отправлена на сервер, размещенный SimpleRisk. Предоставленная регистрационная информация будет использоваться SimpleRisk для уведомления клиентов о новых выпусках и обновлениях безопасности. Акт регистрации SimpleRisk позволит вам получать наши маркетинговые сообщения, но вы можете отказаться в любое время, используя ссылку для отказа от подписки в этих сообщениях. SimpleRisk уважает конфиденциальность наших клиентов, и информация, предоставленная нам в процессе регистрации SimpleRisk, никогда не будет продана третьей стороне.',
